-- KSP Dominion Command OS foundation schema: tenancy, RBAC/ABAC, audit, approvals, CRM, projects, finance, documents, jobs, integrations, AI.
create extension if not exists pgcrypto;
create type app_role as enum ('founder_ceo','executive_operations','project_manager','department_lead','developer','designer','capture_specialist','videographer','photographer','editor','content_specialist','marketing_specialist','sales_specialist','contractor','freelancer','intern','client');
create type data_classification as enum ('public','internal','confidential','restricted');
create type record_status as enum ('draft','active','pending_approval','approved','posted','locked','archived','rejected','quarantined');
create table organizations (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, status record_status not null default 'active', created_at timestamptz not null default now());
create table profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null, email text not null, status record_status not null default 'active', mfa_required boolean not null default true, created_at timestamptz not null default now());
create table memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), profile_id uuid not null references profiles(id), role app_role not null, department text, scope text not null default 'assigned', effective_from timestamptz not null default now(), effective_until timestamptz, suspended_at timestamptz, created_at timestamptz not null default now(), unique(organization_id, profile_id, role));
create table audit_events (id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), actor_id uuid references profiles(id), action text not null, target_table text, target_id uuid, classification data_classification not null default 'internal', metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table clients (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), legal_name text not null, display_name text not null, relationship_health text not null default 'unknown', status record_status not null default 'active', internal_notes text, created_at timestamptz not null default now(), created_by uuid references profiles(id), archived_at timestamptz);
create table contacts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), client_id uuid references clients(id), name text not null, email text, phone text, client_visible boolean not null default false, classification data_classification not null default 'internal', created_at timestamptz not null default now());
create table leads (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), owner_id uuid not null references profiles(id), name text not null, source text, expected_value_minor bigint check (expected_value_minor >= 0), currency char(3), probability numeric(5,2) check (probability between 0 and 100), target_close_date date, next_action text, status record_status not null default 'active', created_at timestamptz not null default now(), check (status <> 'active' or next_action is not null));
create table projects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), client_id uuid references clients(id), name text not null, project_type text not null, health text not null default 'unknown', budget_minor bigint check (budget_minor >= 0), currency char(3), next_action text, status record_status not null default 'active', created_at timestamptz not null default now(), archived_at timestamptz);
create table project_memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), project_id uuid not null references projects(id) on delete cascade, profile_id uuid not null references profiles(id), role app_role not null, effective_until timestamptz, unique(project_id, profile_id));
create table tasks (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), project_id uuid references projects(id), owner_id uuid references profiles(id), title text not null, due_date date, blocked boolean not null default false, client_visible boolean not null default false, classification data_classification not null default 'internal', status record_status not null default 'active', created_at timestamptz not null default now());
create table approval_requests (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), requester_id uuid not null references profiles(id), approval_type text not null, amount_minor bigint, currency char(3), risk_level text not null, evidence jsonb not null default '[]', status record_status not null default 'pending_approval', due_at timestamptz, created_at timestamptz not null default now());
create table approval_decisions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), approval_request_id uuid not null references approval_requests(id) on delete cascade, approver_id uuid not null references profiles(id), decision text not null check (decision in ('approved','rejected')), comments text, created_at timestamptz not null default now(), unique(approval_request_id, approver_id));
create table chart_accounts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), code text not null, name text not null, account_type text not null, status record_status not null default 'active', unique(organization_id, code));
create table journal_entries (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), memo text, status record_status not null default 'draft', posted_at timestamptz, reversed_entry_id uuid references journal_entries(id), created_at timestamptz not null default now(), check ((status='posted') = (posted_at is not null) or status <> 'posted'));
create table journal_lines (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), journal_entry_id uuid not null references journal_entries(id) on delete restrict, account_id uuid not null references chart_accounts(id), debit_minor bigint not null default 0 check (debit_minor >= 0), credit_minor bigint not null default 0 check (credit_minor >= 0), currency char(3) not null, project_id uuid references projects(id), client_id uuid references clients(id), check (debit_minor <> credit_minor));
create table documents (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), client_id uuid references clients(id), project_id uuid references projects(id), title text not null, storage_path text not null, checksum text, classification data_classification not null default 'confidential', client_visible boolean not null default false, retention_category text, legal_hold boolean not null default false, status record_status not null default 'active', created_at timestamptz not null default now());
create table inbox_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), created_by uuid references profiles(id), item_type text not null, title text not null, body text, triage_status text not null default 'new', target_table text, target_id uuid, classification data_classification not null default 'internal', created_at timestamptz not null default now());
create table subscriptions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), vendor text not null, product text not null, owner_id uuid references profiles(id), cost_minor bigint not null check(cost_minor >= 0), currency char(3) not null, billing_frequency text not null, renewal_date date, auto_renewal boolean not null default false, status record_status not null default 'active');
create table integration_connections (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), provider text not null, scopes text[] not null default '{}', token_expires_at timestamptz, status record_status not null default 'active', metadata jsonb not null default '{}', unique(organization_id, provider));
create table background_jobs (id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id), job_type text not null, idempotency_key text not null unique, status text not null default 'queued', attempts int not null default 0, payload jsonb not null default '{}', run_after timestamptz not null default now(), created_at timestamptz not null default now());
create table ai_actions (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id), actor_id uuid references profiles(id), action_type text not null, requested_scope jsonb not null default '{}', model_provider text, input_refs jsonb not null default '[]', output jsonb, confidence numeric(5,2), human_reviewer uuid references profiles(id), approval_status record_status not null default 'draft', execution_status text not null default 'pending_review', failure_reason text, created_at timestamptz not null default now());
create or replace function current_org_ids() returns setof uuid language sql stable as $$ select organization_id from memberships where profile_id = auth.uid() and suspended_at is null and (effective_until is null or effective_until > now()) $$;
create or replace function is_executive(org uuid) returns boolean language sql stable as $$ select exists(select 1 from memberships where profile_id=auth.uid() and organization_id=org and role in ('founder_ceo','executive_operations') and suspended_at is null and (effective_until is null or effective_until > now())) $$;
create or replace function can_access_project(pid uuid) returns boolean language sql stable as $$ select exists(select 1 from project_memberships pm where pm.project_id=pid and pm.profile_id=auth.uid() and (pm.effective_until is null or pm.effective_until > now())) $$;
create or replace function prevent_posted_journal_update() returns trigger language plpgsql as $$ begin if old.status='posted' then raise exception 'posted_journal_entries_are_immutable'; end if; return new; end $$;
create trigger journal_entries_immutable before update or delete on journal_entries for each row execute function prevent_posted_journal_update();
alter table organizations enable row level security; alter table profiles enable row level security; alter table memberships enable row level security; alter table audit_events enable row level security; alter table clients enable row level security; alter table contacts enable row level security; alter table leads enable row level security; alter table projects enable row level security; alter table project_memberships enable row level security; alter table tasks enable row level security; alter table approval_requests enable row level security; alter table approval_decisions enable row level security; alter table chart_accounts enable row level security; alter table journal_entries enable row level security; alter table journal_lines enable row level security; alter table documents enable row level security; alter table inbox_items enable row level security; alter table subscriptions enable row level security; alter table integration_connections enable row level security; alter table background_jobs enable row level security; alter table ai_actions enable row level security;
create policy org_member_read on organizations for select using (id in (select current_org_ids()));
create policy own_profile_read on profiles for select using (id = auth.uid());
create policy member_read on memberships for select using (organization_id in (select current_org_ids()));
create policy audit_executive_read on audit_events for select using (is_executive(organization_id));
create policy clients_member_read on clients for select using (organization_id in (select current_org_ids()) and (is_executive(organization_id) or internal_notes is null));
create policy contacts_member_read on contacts for select using (organization_id in (select current_org_ids()));
create policy leads_member_read on leads for select using (organization_id in (select current_org_ids()));
create policy projects_member_read on projects for select using (organization_id in (select current_org_ids()) and (is_executive(organization_id) or can_access_project(id)));
create policy project_members_read on project_memberships for select using (organization_id in (select current_org_ids()) and (is_executive(organization_id) or can_access_project(project_id)));
create policy tasks_project_read on tasks for select using (organization_id in (select current_org_ids()) and (is_executive(organization_id) or project_id is null or can_access_project(project_id)));
create policy approvals_executive_read on approval_requests for select using (is_executive(organization_id) or requester_id=auth.uid());
create policy approval_decisions_executive_read on approval_decisions for select using (is_executive(organization_id) or approver_id=auth.uid());
create policy finance_executive_read on chart_accounts for select using (is_executive(organization_id));
create policy journal_entries_executive_read on journal_entries for select using (is_executive(organization_id));
create policy journal_lines_executive_read on journal_lines for select using (is_executive(organization_id));
create policy documents_member_read on documents for select using (organization_id in (select current_org_ids()) and (is_executive(organization_id) or classification <> 'restricted'));
create policy inbox_owner_read on inbox_items for select using (organization_id in (select current_org_ids()) and (is_executive(organization_id) or created_by=auth.uid()));
create policy subscriptions_executive_read on subscriptions for select using (is_executive(organization_id));
create policy integrations_admin_read on integration_connections for select using (is_executive(organization_id));
create policy jobs_admin_read on background_jobs for select using (organization_id is null or is_executive(organization_id));
create policy ai_actions_actor_read on ai_actions for select using (is_executive(organization_id) or actor_id=auth.uid());
create policy no_self_approval_insert on approval_decisions for insert with check (approver_id = auth.uid() and not exists (select 1 from approval_requests ar where ar.id=approval_request_id and ar.requester_id=auth.uid()) and is_executive(organization_id));
